import{_ as s,o as a,c as r,a0 as o}from"./chunks/framework.BdKrsJIB.js";const u=JSON.parse('{"title":"Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"explanation/architecture.md","filePath":"explanation/architecture.md"}'),n={name:"explanation/architecture.md"};function i(t,e,c,d,l,p){return a(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h1><p>Tarsi is the org&#39;s <strong>release plane</strong>: one pure domain core, a config loader, an ops wire, a publish port — and nothing else. It answers questions about releases; it never decides <em>when</em> to release or <em>who</em> approves.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> caller (human, agent, peregrin campaign, scripts/release.sh)</span></span>
<span class="line"><span>        │  ndjson {&quot;op&quot;: …, &quot;params&quot;: …}  or  one-shot argv</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   tarsi-serve ────────── hypha-serve-cli (shared arg→params shim)</span></span>
<span class="line"><span>        │                       │</span></span>
<span class="line"><span>        │  plans · bumps ·      │ tarsi.toml / type: tarsi profiles</span></span>
<span class="line"><span>        │  changelogs · tags    │ (scarab-config FileSource/Layered)</span></span>
<span class="line"><span>        ▼                       ▼</span></span>
<span class="line"><span>   tarsi-core (pure)      tarsi-manifest (Cargo.toml scan/patch)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   lasius-vcs ── git history, tags, push (tarsi-core never touches git)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>   tarsi-publish port ── crates / ghreleases / dryrun impls</span></span></code></pre></div><h2 id="the-pieces" tabindex="-1">The pieces <a class="header-anchor" href="#the-pieces" aria-label="Permalink to &quot;The pieces&quot;">​</a></h2><ul><li><strong><code>tarsi-core</code></strong> — pure release domain: plans, units, semver bumps, commit classification, changelog rendering. No I/O.</li><li><strong><code>tarsi-manifest</code></strong> — Cargo manifest scanning: workspace members → <code>ReleaseUnitSpec</code>, version reads/writes via <code>toml_edit</code>.</li><li><strong><code>tarsi-config</code></strong> — <code>tarsi.toml</code>/<code>.yml</code> loading (scarab-config) plus <code>type: tarsi</code> profile-pack resolution.</li><li><strong><code>tarsi-serve</code></strong> — the ops surface: <code>manifest</code> / <code>profiles</code> / <code>plan</code> / <code>changelog</code> / <code>notes</code> / <code>check</code> / <code>schema</code> / <code>bump</code> / <code>tag</code> / <code>publish</code> / <code>release</code>. No <code>tarsi</code> CLI exists.</li><li><strong><code>tarsi-publish</code></strong> + <code>-crates</code> / <code>-ghreleases</code> / <code>-dryrun</code> — the publish port and per-forge impls.</li><li><strong><code>tarsi-driver</code></strong> — <code>tamias-driver-tarsi</code>: the <code>type: tarsi</code> pack driver, plus a read-only pavo view.</li><li><strong><code>tarsi-testkit</code></strong> — conformance fixtures + golden corpus.</li></ul><h2 id="the-ops-wire" tabindex="-1">The ops wire <a class="header-anchor" href="#the-ops-wire" aria-label="Permalink to &quot;The ops wire&quot;">​</a></h2><p>Two modes over the same ops: no args = ndjson JSON-lines on stdio; <code>&lt;op&gt; [--dir D] [--set k=v] [--yes|--dry-run]</code> = one-shot argv via the shared <code>hypha-serve-cli</code> shim. <code>release</code>-family ops are <strong>dry-run by default</strong> — mutation requires <code>dry_run: false</code> (<code>--yes</code>). Humans, agents, and peregrin campaigns speak identical wire; there is deliberately no <code>tarsi-llm</code>.</p><h2 id="profiles-are-packs" tabindex="-1">Profiles are packs <a class="header-anchor" href="#profiles-are-packs" aria-label="Permalink to &quot;Profiles are packs&quot;">​</a></h2><p>Org release conventions ship as <code>type: tarsi</code> tamias packs (<code>libraries/9aia-release</code>) — layered config, versioned by the tamias store. <code>tamias-driver-tarsi</code> validates and installs them; <code>tarsi-config</code> resolves the layers through scarab-config&#39;s <code>FileSource</code>/<code>LayeredFileSource</code>.</p><h2 id="where-it-sits" tabindex="-1">Where it sits <a class="header-anchor" href="#where-it-sits" aria-label="Permalink to &quot;Where it sits&quot;">​</a></h2><p>In the org&#39;s layering — <strong>tamias</strong> (package &amp; content manager) → <strong>engines</strong> (myco records, kuda code maps, mimus proofs, sepia sessions, sturn coordination, hypha substrate, cicada schedules, cypera docs, scarab config, peregrin orchestration) → <strong>surfaces</strong> (pavo views, MCP fronts).</p><p>Tarsi sits at the <strong>release plane beside the engines</strong>: every repo&#39;s <code>scripts/release.sh</code> is a thin shim over <code>tarsi-serve</code>, org conventions ride tamias profile packs, and peregrin&#39;s <code>libraries/release</code> campaign drives the same ops — tarsi computes plans and mutations; orchestration decides when to run them.</p><h2 id="deeper-reads" tabindex="-1">Deeper reads <a class="header-anchor" href="#deeper-reads" aria-label="Permalink to &quot;Deeper reads&quot;">​</a></h2><ul><li><a href="./release-semantics.html">Release semantics</a> — the load-bearing rules (dry-run default, per-unit tags, ordering, rollback).</li><li><a href="./boundaries.html">Boundaries</a> — owns / doesn&#39;t-own, neighbors named.</li><li><a href="./concepts.html">Concepts</a> — units, strategies, profiles, the wire.</li><li><a href="./decisions.html">Decisions</a> — ADR-lite.</li></ul>`,14)])])}const g=s(n,[["render",i]]);export{u as __pageData,g as default};
